mapper.select:
SELECT a.id, a.worker_id, w.name AS worker_name, w.phone AS worker_phone, a.real_name, a.id_card_no, a.id_card_front_url, a.id_card_back_url, a.status, a.reject_reason, a.submitted_at, a.reviewed_at, a.reviewer_id, a.created_at, a.updated_at FROM worker_real_name_auth a LEFT JOIN c_worker w ON w.id = a.worker_id
a.status = #{status}
ORDER BY a.submitted_at DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE worker_real_name_auth
SET status = #{status},
    reject_reason = #{rejectReason},
    reviewer_id = #{reviewerId},
    reviewed_at = #{reviewedAt}
WHERE id = #{id}
